import{_ as t}from"./chunks/100.I7A0VXqr.js";import{_ as o,o as r,c as i,ak as n}from"./chunks/framework.DC-k2h36.js";const a="/projects/esp32Sensor/en/latest/assets/1.c7P2gSco.webp",s="/projects/esp32Sensor/en/latest/assets/2.Bm28qQn-.webp",l="/projects/esp32Sensor/en/latest/assets/3.CqQQqWCQ.webp",c="/projects/esp32Sensor/en/latest/assets/4.DRGk6byG.webp",y=JSON.parse('{"title":"10. Color Sensor","description":"","frontmatter":{},"headers":[],"relativePath":"docs/10. Color Sensor.md","filePath":"docs/10. Color Sensor.md"}'),d={name:"docs/10. Color Sensor.md"};function h(p,e,g,m,u,_){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="_10-color-sensor" tabindex="-1">10. Color Sensor <a class="header-anchor" href="#_10-color-sensor" aria-label="Permalink to &quot;10. Color Sensor&quot;">​</a></h1><h2 id="_10-1-introduction" tabindex="-1">10.1 Introduction <a class="header-anchor" href="#_10-1-introduction" aria-label="Permalink to &quot;10.1 Introduction&quot;">​</a></h2><p>Equipped with a high-sensitivity optical chip, the color sensor precisely analyzes light wave intensity to accomplish complex color recognition. It converts red, green, blue, and infrared light into digital signals. With its wide dynamic response range, the sensor accurately outputs color data in both low-light and bright-light environments.</p><img loading="lazy" height="1156" width="1156" src="'+a+'" class="common_img" style="width:300px;"><h2 id="_10-2-technical-specifications" tabindex="-1">10.2 Technical Specifications <a class="header-anchor" href="#_10-2-technical-specifications" aria-label="Permalink to &quot;10.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Color detection</td><td style="text-align:center;">Identifies RGB colors and infrared light intensity</td></tr><tr><td style="text-align:center;">Detection distance</td><td style="text-align:center;">15 ± 2 mm</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">39.5 × 23.4 × 16.7 mm</td></tr></tbody></table><h2 id="_10-3-hands-on-project" tabindex="-1">10.3 Hands-On Project <a class="header-anchor" href="#_10-3-hands-on-project" aria-label="Permalink to &quot;10.3 Hands-On Project&quot;">​</a></h2><h3 id="_10-3-1-project-overview" tabindex="-1">10.3.1 Project Overview <a class="header-anchor" href="#_10-3-1-project-overview" aria-label="Permalink to &quot;10.3.1 Project Overview&quot;">​</a></h3><p>This project uses the color sensor and onboard RGB LEDs to create interactive, color-matching light effects. When the sensor detects red, green, or blue, the onboard RGB LEDs light up in that same color. Otherwise, the LEDs turn off. This project demonstrates color sensor initialization and nested if-else conditional logic.</p><h3 id="_10-3-2-hardware-wiring" tabindex="-1">10.3.2 Hardware Wiring <a class="header-anchor" href="#_10-3-2-hardware-wiring" aria-label="Permalink to &quot;10.3.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the color sensor to port <strong>P1</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="588" width="620" src="'+s+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This sensor supports connection to any port among P1, P2, P3, or P4 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h3 id="_10-3-3-adding-extensions" tabindex="-1">10.3.3 Adding Extensions <a class="header-anchor" href="#_10-3-3-adding-extensions" aria-label="Permalink to &quot;10.3.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Color recognition sensor</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><h3 id="_10-3-4-complete-program-and-analysis" tabindex="-1">10.3.4 Complete Program and Analysis <a class="header-anchor" href="#_10-3-4-complete-program-and-analysis" aria-label="Permalink to &quot;10.3.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Upon start-up, the hardware port of the color sensor is initialized to port P1.</p></li><li><p>Inside the main program loop, the color information recognized by the color sensor is read to perform conditional judgment:</p><ul><li><p>When red is detected, all RGB LEDs are set to illuminate in red.</p></li><li><p>When green is detected, all RGB LEDs are set to illuminate in green.</p></li><li><p>When blue is detected, all RGB LEDs are set to illuminate in blue.</p></li><li><p>When none of these conditions are met, all RGB LEDs turn off.</p></li></ul></li><li><p>A 0.1 s delay is executed at the end of each loop iteration before repeating the entire color detection and lighting routine.</p></li></ol><img loading="lazy" height="763" width="483" src="'+c+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">01 Program Files/10 Color Sensor.sb3</a>.</strong></p></div><h3 id="_10-3-5-program-upload" tabindex="-1">10.3.5 Program Upload <a class="header-anchor" href="#_10-3-5-program-upload" aria-label="Permalink to &quot;10.3.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+t+'" class="common_img" style="width:800px;"><h3 id="_10-3-6-program-outcome" tabindex="-1">10.3.6 Program Outcome <a class="header-anchor" href="#_10-3-6-program-outcome" aria-label="Permalink to &quot;10.3.6 Program Outcome&quot;">​</a></h3><p>Once the program upload is complete, place blocks of different colors close to the recognition area of the color sensor. When a red block is recognized, the RGB LEDs illuminate in red. When a green block is recognized, the RGB LEDs illuminate in green. When a blue block is recognized, the RGB LEDs illuminate in blue. Placing objects of other colors turns off the RGB LEDs, delivering synchronized visual feedback for color recognition.</p>',25)])])}const x=o(d,[["render",h]]);export{y as __pageData,x as default};
